package communication;import cern.cmw.data.Data;import codec.JavaToCMWD;import codec.javatolv.LVDataEncoder;import codec.javatolv.LVTypeEncoder;import codec.lvtojava.LVDecoder;import jakarta.servlet.ServletException;import jakarta.servlet.ServletInputStream;import jakarta.servlet.ServletOutputStream;import jakarta.servlet.http.HttpServlet;import jakarta.servlet.http.HttpServletRequest;import jakarta.servlet.http.HttpServletResponse;import types.JavaContainer;import java.io.ByteArrayOutputStream;import java.io.IOException;public class CodecTestListener extends HttpServlet {    private static final char[] HEX_ARRAY = "0123456789ABCDEF".toCharArray();        /**         * @param args         */        public static void main(String[] args) {                    }        public void doPost(HttpServletRequest request, HttpServletResponse response) throws IOException {            ServletInputStream reader = request.getInputStream();            ServletOutputStream out = response.getOutputStream();            byte[] message = reader.readAllBytes();            JavaContainer jc = null;            try {                jc = LVDecoder.decode(message);            } catch (ClassNotFoundException | NoSuchMethodException e) {                throw new RuntimeException(e);            }            System.out.println(jc);            Data data = JavaToCMWD.encode(jc);            System.out.println(data);            byte[] dataBytes = LVDataEncoder.serialise(jc);            byte[] typeStringBytes = LVTypeEncoder.encodeTypeDescriptor(jc);            ByteArrayOutputStream outputStream = new ByteArrayOutputStream( );            outputStream.write( typeStringBytes );            outputStream.write(".....".getBytes());            outputStream.write( dataBytes );            outputStream.writeTo(out);        }    public static String bytesToHex(byte[] bytes) {        char[] hexChars = new char[bytes.length * 2];        for (int j = 0; j < bytes.length; j++) {            int v = bytes[j] & 0xFF;            hexChars[j * 2] = HEX_ARRAY[v >>> 4];            hexChars[j * 2 + 1] = HEX_ARRAY[v & 0x0F];        }        return new String(hexChars);    }    @Override    public void doGet(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {        doPost(req, resp);    }}